import{z as C,x as i,o as t,c as B,q as r,j as o,D as e,d as E,s as l,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SACK","description":"","frontmatter":{"title":"SACK","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tcp-sack.md","filePath":"cs/tcp-sack.md","lastUpdated":1791063341000}'),d={name:"cs/tcp-sack.md"};function p(K,a,S,c,m,D){const s=i("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="sack" tabindex="-1">SACK <a class="header-anchor" href="#sack" aria-label="Permalink to &quot;SACK&quot;">​</a></h1><div class="epigraph"><p>累计 ACK 只推进前缀；选择确认把已收到的不连续块告诉发送方，重传针对空洞而不是从洞口整段重来。</p><footer>—— 据 RFC 2018 选择确认；RFC 793 的累计确认仍是基线；Kurose and Ross</footer></div><p><a href="/cs/tcp-rto">上一课</a>钉死何时超时重传。本课不重做 Karn。缺口是丢包形状：窗口里丢了中间几段时，累计 ACK 反复报同一个前缀，发送方只能猜或超时后从洞口重拉。SACK 选项列出已收到的序号块。本课不把接收窗口通告写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/cs/tcp-seq-rexmit">序号与重传</a> 用累计 ACK。管道长、窗口大时，一次丢几个段会导致不必要的重传（Go-Back-N 式浪费）。SACK：接收方在 ACK 里带若干块「左沿、右沿」；发送方维护计分板，只重发未被累计也未被 SACK 覆盖的段。缺口是<strong>空洞的显式信号</strong>，仍服从累计 ACK 推进提交序号。</p><p><span class="marginnote">SACK 是选项，需握手协商。DSACK 后来报告重复收到的块，帮助区分重传与乱序。本课只钉选择确认的数据平面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收乱序段：缓存在重组队列，发 ACK（常带 SACK）。发送方根据计分板决定重传集合；累计 ACK 前移时裁掉计分板前缀。与 RTO 的关系：SACK 不取消超时，只减少盲目重传。流控窗口下一课才限制「能飞多少」。</p>',8)),(t(),o(n,null,{default:e(()=>[l(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOLE%5B%22%E7%AA%97%E5%8F%A3%E4%B8%AD%E7%9A%84%E7%A9%BA%E6%B4%9E%22%5D%20--%3E%20CUM%5B%22%E7%B4%AF%E8%AE%A1%20ACK%20%E5%81%9C%E5%9C%A8%E6%B4%9E%E5%8F%A3%22%5D%0A%20%20CUM%20--%3E%20SB%5B%22SACK%20%E5%9D%97%E5%A1%AB%E8%AE%A1%E5%88%86%E6%9D%BF%22%5D%0A%20%20SB%20--%3E%20REX%5B%22%E5%8F%AA%E9%87%8D%E5%8F%91%E7%A9%BA%E6%B4%9E%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("p",null,[A("span",{class:"marginnote"},"数字实例：发 8 段、第 3 段丢了，累计 ACK 只能停在 2。没有 SACK 时发送方常把第 2 段之后的 6 段全部重发；有 SACK 就只补 1 段——重传量从 6 段降到 1 段。")],-1)),a[4]||(a[4]=A("h2",{id:"机制",tabindex:"-1"},[E("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=A("p",null,[E("SACK 把接收缓冲的占用情况部分暴露给发送方，使重传与 "),A("a",{href:"/cs/io-dma"},"DMA"),E(" 进出的字节更接近真实丢失。它不增加可靠性规格：没有 SACK 的 TCP 仍可靠，只是更慢、更浪费。端到端校验与序号仍然是正确性来源。")],-1)),a[6]||(a[6]=A("p",null,"用一次具体丢包走一遍计分板：第 3 段与第 5 段丢失时，各报文与计数如何配合。",-1)),(t(),o(n,null,{default:e(()=>[l(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEND%5B%22%E5%8F%91%E9%80%81%E6%96%B9%E5%8F%91%E5%87%BA%201%20%E5%88%B0%208%20%E6%AE%B5%22%5D%20--%3E%20LOSS%5B%22%E7%AC%AC%203%20%E6%AE%B5%E4%B8%8E%E7%AC%AC%205%20%E6%AE%B5%E5%9C%A8%E8%B7%AF%E4%B8%8A%E4%B8%A2%E5%A4%B1%22%5D%0A%20%20LOSS%20--%3E%20ARR%5B%221%202%204%206%207%208%20%E5%85%88%E5%90%8E%E5%88%B0%E8%BE%BE%22%5D%0A%20%20ARR%20--%3E%20ACK3%5B%22%E7%B4%AF%E8%AE%A1%20ACK%20%E5%81%9C%E5%9C%A8%203%22%5D%0A%20%20ACK3%20--%3E%20BLOCKS%5B%22SACK%20%E5%9D%97%3A%204%20%E5%88%B0%204%20%E4%B8%8E%206%20%E5%88%B0%208%22%5D%0A%20%20BLOCKS%20--%3E%20BOARD%5B%22%E8%AE%A1%E5%88%86%E6%9D%BF%E6%98%BE%E7%A4%BA%E5%8F%AA%E7%BC%BA%203%20%E4%B8%8E%205%22%5D%0A%20%20BOARD%20--%3E%20FIX%5B%22%E5%8F%AA%E9%87%8D%E4%BC%A0%203%20%E4%B8%8E%205%2C%20%E5%85%B6%E4%BD%99%E4%B8%8D%E5%8A%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">术语翻译：&quot;计分板&quot;是发送方维护的清单，给每个已发未确认的段记账——被 SACK 覆盖的打勾、被累计确认推进的划掉，剩下的就是要重传的段。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 FACK 与全部恢复算法当标准必背，不引入 QUIC 的 ACK 范围作为本课对象（后课对照）。接收方还能收多少字节，下一课 <code>rwnd</code>。</p><p>后课默认：发送方可以知道哪些块已到。发送太多仍会淹没对端缓冲，下一课流控。</p><p><span class="marginnote">常见误区：容易以为 SACK 取代了累计 ACK。实际上 ACK 报文里的累计确认字段照常存在并推进提交序号，SACK 块只是附加情报，防止把已经到的段再发一遍。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SACK 报告不连续块；重传对准空洞。</li><li>累计 ACK 仍是提交前缀。</li><li>接收窗口是下一课。</li><li>出处：RFC 2018；RFC 793；Kurose and Ross。</li></ul>',7))])}const f=C(d,[["render",p]]);export{h as __pageData,f as default};
